// Concatenates src/*.js into dist/Code.gs for people who prefer to copy and paste
// one file into the Apps Script editor instead of using clasp.
const fs = require('fs');
const path = require('path');

const order = ['Main.js', 'Parse.js', 'Storage.js', 'Digest.js'];
const root = path.join(__dirname, '..');
const banner = `/**
 * Job alerts — single-file build of src/ (generated by tools/bundle.js; edit src/, not this file).
 * Paste into Extensions → Apps Script in your tracker spreadsheet. See README.md.
 */\n\n`;
const body = order.map((f) => `// ===== ${f} =====\n\n` + fs.readFileSync(path.join(root, 'src', f), 'utf8')).join('\n');
fs.mkdirSync(path.join(root, 'dist'), { recursive: true });
fs.writeFileSync(path.join(root, 'dist', 'Code.gs'), banner + body);
console.log('Wrote dist/Code.gs');
